m=np.arange(1,61);B0=400e6;r=.08125/12;A=B0*r/(1-(1+r)**-360);bal=B0*(1+r)**m-A*((1+r)**m-1)/r;prev=np.r_[B0,bal[:-1]];inte=(.08125-.00625)/12*prev;prin=A-r*prev;ax.bar(m,inte/1e6,label='Net interest (7.50%)',color=ACCENT);ax.bar(m,prin/1e6,bottom=inte/1e6,label='Scheduled principal',color=GOOD);ax.set_xlabel('Month');ax.set_ylabel('Cash flow (USD M)');ax.set_title('First five years of a $400M pass-through',loc='left');ax.set_ylim(0,3.4);ax.legend(fontsize=8,loc='upper center',ncol=2)
